const i=()=>({setItem:(e,o)=>{try{const t=window.localStorage.getItem(e);if(t==null||t==null){const r=[o];window.localStorage.setItem(e,JSON.stringify(r))}else{const r=JSON.parse(t);r.push(o),window.localStorage.setItem(e,JSON.stringify(r))}}catch(t){console.error("LocalStorage save error:",t)}},getItem:e=>{try{const o=window.localStorage.getItem(e);return o?JSON.parse(o):null}catch{return null}},deleteItem:(e,o)=>{try{const t=window.localStorage.getItem(e);if(t==null||t==null)return;const s=JSON.parse(t).filter(n=>n!==o);window.localStorage.setItem(e,JSON.stringify(s))}catch(t){console.error("LocalStorage save error:",t)}}});export{i as u};
